<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner Control — Live Lab Store Offers</title><style>:root{color-scheme:dark;font-family:system-ui,sans-serif}body{margin:0;background:#111820;color:#f4f7fb;padding:24px}main{max-width:1120px;margin:auto}a{color:#f6cc65}.lede,.meta{color:#b8c6d2}.cards{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));margin-top:20px}.card{background:#1b2530;border:1px solid #33404c;border-radius:12px;overflow:hidden}.copy{padding:16px}.card h2{margin:0 0 8px;font-size:1.1rem}.card p{margin:6px 0;color:#b8c6d2}.media{display:block;width:100%;height:170px;object-fit:contain;background:#0d141c}.fallback{display:grid;place-items:center;width:100%;height:170px;background:#0d141c;color:#b8c6d2}#status{min-height:1.5em;padding:12px;border-left:3px solid #f6cc65;background:#18232e}#more{width:auto;padding:9px 14px;margin-top:16px}@media(max-width:560px){body{padding:16px}.cards{grid-template-columns:1fr}}</style></head><body><main><p><a href="/owner-control/v1/index.php">← Owner Control</a></p><?php if ($draftsAvailable): ?><p><a href="/owner-control/v1/lab-store-drafts.php">Open Draft Workspace — private drafts, not live offers</a></p><?php endif; ?><h1>Live Lab Store Offers</h1><p class="lede">Current shop state — read only. No publish, activation, edit, purchase, or fulfillment controls are available.</p><p id="status" role="status">Loading current offers…</p><section id="cards" class="cards" aria-label="Current Lab Store offers"></section><button id="more" type="button" hidden>Show more</button></main><script>'use strict';const fields=['offer_id','title','category','source_type','offer_active','source_available','lp_price','dspoinc_price','stock','presentation_ref','media_kind'],cards=document.getElementById('cards'),status=document.getElementById('status'),more=document.getElementById('more');let cursor=null;function valid(o){return o&&typeof o==='object'&&Object.keys(o).every(k=>fields.includes(k))&&Number.isInteger(o.offer_id)&&typeof o.title==='string'&&typeof o.category==='string'&&(o.source_type==='normal_store'||o.source_type==='genetic_item')&&typeof o.offer_active==='boolean'&&typeof o.source_available==='boolean'&&(Number.isInteger(o.lp_price)||o.lp_price===null)&&(Number.isInteger(o.dspoinc_price)||o.dspoinc_price===null)&&Number.isInteger(o.stock)&&(typeof o.presentation_ref==='string'||o.presentation_ref===null)&&(o.media_kind==='image'||o.media_kind==='media_unavailable')}function fallback(){const e=document.createElement('p');e.className='fallback';e.textContent='Media unavailable';return e}function card(o){const e=document.createElement('article'),image=o.presentation_ref?document.createElement('img'):null,copy=document.createElement('div'),title=document.createElement('h2'),state=document.createElement('p'),commercial=document.createElement('p');e.className='card';copy.className='copy';if(image){image.className='media';image.alt='';image.src=o.presentation_ref;image.addEventListener('error',()=>image.replaceWith(fallback()),{once:true});e.append(image)}else e.append(fallback());title.textContent='#'+o.offer_id+' · '+o.title;state.textContent=o.category+' · '+(o.offer_active?'Active':'Disabled')+' · '+(o.source_available?'Source available':'Source unavailable');commercial.textContent='LP: '+(o.lp_price===null?'Not offered':String(o.lp_price))+' · DSPOINC: '+(o.dspoinc_price===null?'Not offered':String(o.dspoinc_price))+' · Stock: '+String(o.stock);copy.append(title,state,commercial);e.append(copy);return e}async function load(next){try{const url='/api/owner-control/v1/lab-store/live-offers.php?limit=25'+(next&&cursor?'&cursor='+encodeURIComponent(cursor):''),r=await fetch(url,{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p||p.success!==true||p.capability!=='owner_control_lab_store_live_offers_read'||p.mode!=='read_only'||p.writes!==false||!p.page||!Array.isArray(p.offers)||!p.offers.every(valid))throw Error();const f=document.createDocumentFragment();p.offers.forEach(o=>f.append(card(o)));if(next)cards.append(f);else cards.replaceChildren(f);cursor=typeof p.page.next_cursor==='string'?p.page.next_cursor:null;more.hidden=cursor===null;status.textContent=p.offers.length?'Read-only current shop state loaded.':'No live offer records are available.'}catch{if(!next)cards.replaceChildren();more.hidden=true;status.textContent='Live offer presentation is currently unavailable.'}}more.onclick=()=>load(true);load(false);</script></body></html>
